#!/usr/bin/env python3
"""Keep the capacity-only CAN source frozen; copy it for the wider ISA study."""

from pathlib import Path

from build_can_duplex import generate as combined_source


def generate():
    source = combined_source()
    source = source.replace_comment_text(
        "GENERATED by build_can_duplex.py. Capacity-only; not simulated.",
        "GENERATED by build_can_frontier.py. Isolated1024x18 study only.",
    )
    return source.replace_comment_text(
        "Operation1=RX,2=TX. Branch target encoding beyond512 is unresolved.",
        "Operation1=RX,2=TX. Generic18-bit encoding; production128-word capacity unchanged.",
    )


if __name__ == "__main__":
    Path(__file__).with_name("can_frontier_candidate.asm").write_text(
        generate().to_asm()
    )
